-- migrations/pg/001_initial.sql — PostgreSQL 15+ 初始 schema。
--
-- 来源：以 MySQL 真库（migrations/001-031 全量应用后）SHOW CREATE TABLE 物化的
-- 权威 DDL（60 表）逐表翻译，形态与 MySQL 侧对齐。
-- 翻译规则：
--   - 类型：varchar(n)/char(n) 保留；text/mediumtext/longtext→text；json→json；
--     int→int；bigint→bigint；double→double precision；datetime[(3)]→timestamp[(3)]
--   - 列型按消费契约翻译：绑 Go bool 参数的 3 列（users.must_change_password、
--     gateway_routes.enabled、ci_attr_templates.required）→boolean；
--     其余 16 个 tinyint/tinyint(1) 标志列→smallint（字面量 0/1 与 boolToInt 写入面要求）
--   - AUTO_INCREMENT×6 → GENERATED BY DEFAULT AS IDENTITY
--   - PG 约束名/索引名 schema 全局唯一：UNIQUE KEY `name`×3（ci_types/permissions/roles）
--     → uq_<table>_name；KEY `idx_tenant`×3（alert_silences/notify_channels/notify_templates）
--     → idx_<table>_tenant；其余沿用 MySQL 原名
--   - DEFAULT CURRENT_TIMESTAMP[(3)] → now()；删 ENGINE/CHARSET/COLLATE
--
-- 语义分歧（PG 侧有意不搬，登记备查）：
--   - ci_items.ci_attrs_text 生成列与 FULLTEXT/ngram 索引省略：检索消费路径在 Go 侧，
--     PG 检索对齐列 A3-2
--   - ON UPDATE CURRENT_TIMESTAMP×4 不建触发器：全仓 UPDATE 均显式写 updated_at
--   - schema_migrations 不入此文件：dialect DDL 建表；PG 首装仅含 001
--   - 种子数据不入此文件：与 MySQL 侧一致，种子全在 Go 侧（seedRBAC + INSERT IGNORE 链）
--   - down.sql 不补：MySQL 侧同样无 down.sql，无消费者
--   - 002-031 的 PG 化列 A3-2（migration_test.go 只钉 001，002+ 运行时才需要）
--
-- 运行时接线（server_factory.go / main.go 的 Store=="mysql" 门）不在本批 scope。

CREATE TABLE IF NOT EXISTS "agents" (
  "agent_id" varchar(64) NOT NULL,
  "hostname" varchar(255),
  "segment" varchar(64),
  "tenant_id" varchar(64),
  "addr" varchar(255),
  "grpc_port" int,
  "metrics_port" int,
  "status" varchar(16),
  "load" int,
  "last_seen" timestamp,
  "secret" varchar(64),
  PRIMARY KEY ("agent_id")
);

CREATE TABLE IF NOT EXISTS "alert_rules" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64),
  "metric" varchar(128),
  "op" varchar(8),
  "threshold" double precision,
  "for_duration" int DEFAULT 0,
  "severity" varchar(16),
  "message" text,
  "enabled" smallint DEFAULT 1,
  "created_at" timestamp,
  "created_by" varchar(64),
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "alert_silences" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL,
  "match_labels" json,
  "starts_at" timestamp,
  "ends_at" timestamp,
  "created_by" varchar(64),
  "reason" text,
  "created_at" timestamp,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_alert_silences_tenant" ON "alert_silences" ("tenant_id");

CREATE TABLE IF NOT EXISTS "alerts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "tenant_id" varchar(64),
  "device_id" varchar(64),
  "agent_id" varchar(64),
  "severity" varchar(16),
  "message" text,
  "created_at" timestamp,
  "alert_id" varchar(64),
  "status" varchar(16),
  "acknowledged_by" varchar(64),
  "silenced_until" timestamp,
  "comment" text,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "api_keys" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "key_hash" varchar(128) NOT NULL,
  "scopes" text,
  "rate_limit_per_sec" int NOT NULL DEFAULT 0,
  "expires_at" timestamp,
  "last_used_at" timestamp,
  "enabled" smallint NOT NULL DEFAULT 1,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_apikeys_tenant" ON "api_keys" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_apikeys_hash" ON "api_keys" ("key_hash");
CREATE INDEX IF NOT EXISTS "idx_apikeys_enabled" ON "api_keys" ("tenant_id", "enabled");

CREATE TABLE IF NOT EXISTS "argocd_apps" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "namespace" varchar(255),
  "repo_url" text,
  "path" varchar(512),
  "target_revision" varchar(64),
  "cluster_url" text,
  "sync_policy" varchar(32) NOT NULL DEFAULT 'manual',
  "status" varchar(32) NOT NULL DEFAULT 'unknown',
  "health_status" varchar(32) NOT NULL DEFAULT 'unknown',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_argocd_tenant" ON "argocd_apps" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_argocd_name" ON "argocd_apps" ("tenant_id", "name");

CREATE TABLE IF NOT EXISTS "audit_archive_meta" (
  "id" int NOT NULL,
  "archived_through_id" bigint NOT NULL DEFAULT 0,
  "boundary_hash" char(64) NOT NULL DEFAULT '',
  "archived_rows" bigint NOT NULL DEFAULT 0,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "audit_chain_head" (
  "id" int NOT NULL,
  "last_id" bigint NOT NULL DEFAULT 0,
  "last_hash" char(64) NOT NULL DEFAULT '',
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "audit_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "tenant_id" varchar(64),
  "user_id" varchar(64),
  "action" varchar(64),
  "target" varchar(128),
  "detail" text,
  "created_at" timestamp,
  "trace_id" varchar(64),
  "prev_hash" char(64),
  "entry_hash" char(64),
  "high_risk" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_audit_trace" ON "audit_log" ("trace_id");
CREATE INDEX IF NOT EXISTS "idx_audit_tenant_created" ON "audit_log" ("tenant_id", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "idx_audit_entry_hash" ON "audit_log" ("entry_hash");
CREATE INDEX IF NOT EXISTS "idx_audit_high_risk" ON "audit_log" ("high_risk");

CREATE TABLE IF NOT EXISTS "audit_log_archive" (
  "id" bigint NOT NULL,
  "tenant_id" varchar(64),
  "user_id" varchar(64),
  "action" varchar(64),
  "target" varchar(128),
  "detail" text,
  "created_at" timestamp,
  "trace_id" varchar(64),
  "prev_hash" char(64),
  "entry_hash" char(64),
  "archived_at" timestamp,
  "high_risk" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_audit_archive_tenant_created" ON "audit_log_archive" ("tenant_id", "created_at");

CREATE TABLE IF NOT EXISTS "automation_executions" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "rule_id" varchar(64) NOT NULL,
  "rule_name" varchar(255),
  "status" varchar(32) NOT NULL DEFAULT 'pending',
  "detail" text,
  "started_at" timestamp NOT NULL,
  "ended_at" timestamp,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_auto_exec_tenant" ON "automation_executions" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_auto_exec_rule" ON "automation_executions" ("tenant_id", "rule_id");
CREATE INDEX IF NOT EXISTS "idx_auto_exec_started" ON "automation_executions" ("tenant_id", "started_at");

CREATE TABLE IF NOT EXISTS "automation_rules" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "description" text,
  "trigger_type" varchar(32) NOT NULL,
  "trigger_params" text,
  "actions" text,
  "enabled" smallint NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_auto_rule_tenant" ON "automation_rules" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_auto_rule_enabled" ON "automation_rules" ("tenant_id", "enabled");

CREATE TABLE IF NOT EXISTS "backup_records" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "type" varchar(32) NOT NULL DEFAULT 'full',
  "status" varchar(32) NOT NULL DEFAULT 'creating',
  "size" bigint NOT NULL DEFAULT 0,
  "path" text,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_backup_tenant" ON "backup_records" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_backup_created" ON "backup_records" ("tenant_id", "created_at");

CREATE TABLE IF NOT EXISTS "billing_plans" (
  "id" varchar(64) NOT NULL,
  "name" varchar(255) NOT NULL,
  "price" int NOT NULL DEFAULT 0,
  "interval_spec" varchar(32) NOT NULL DEFAULT 'monthly',
  "features" text,
  "resource_limits" text,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_billing_plans_interval" ON "billing_plans" ("interval_spec");

CREATE TABLE IF NOT EXISTS "ci_attr_templates" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ci_type" varchar(64) NOT NULL,
  "attr_key" varchar(64) NOT NULL,
  "label" varchar(128) NOT NULL,
  "attr_type" varchar(32) DEFAULT 'string',
  "required" boolean DEFAULT false,
  "default_value" text,
  "tenant_id" varchar(64),
  "created_at" timestamp,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_tmpl" UNIQUE ("ci_type", "attr_key")
);

CREATE TABLE IF NOT EXISTS "ci_items" (
  "id" varchar(64) NOT NULL,
  "ci_type" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL,
  "name" varchar(255) NOT NULL,
  "status" varchar(32) DEFAULT 'active',
  "approval_status" varchar(16) DEFAULT 'approved',
  "attrs" json,
  "source" varchar(32) DEFAULT 'manual',
  "agent_id" varchar(64),
  "device_id" varchar(64),
  "version" int DEFAULT 1,
  "created_at" timestamp,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ci_relations" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "source_ci_id" varchar(64) NOT NULL,
  "target_ci_id" varchar(64) NOT NULL,
  "relation_type" varchar(32) NOT NULL,
  "tenant_id" varchar(64),
  "attributes" json,
  "created_at" timestamp,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_rel" UNIQUE ("source_ci_id", "target_ci_id", "relation_type")
);

CREATE TABLE IF NOT EXISTS "ci_types" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(64) NOT NULL,
  "display_name" varchar(64),
  "builtin" smallint DEFAULT 1,
  "created_at" timestamp,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_ci_types_name" UNIQUE ("name")
);

CREATE TABLE IF NOT EXISTS "cloud_accounts" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "workspace_id" varchar(64) NOT NULL DEFAULT '',
  "name" varchar(128) NOT NULL,
  "provider" varchar(32) NOT NULL,
  "region" varchar(64) NOT NULL DEFAULT '',
  "auth_type" varchar(32) NOT NULL,
  "credentials_ref" varchar(256) NOT NULL DEFAULT '',
  "status" varchar(32) NOT NULL DEFAULT 'active',
  "sync_status" varchar(32) NOT NULL DEFAULT 'pending',
  "last_sync_at" timestamp,
  "discovered_count" int NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT now(),
  "updated_at" timestamp NOT NULL DEFAULT now(),
  "created_by" varchar(128) NOT NULL DEFAULT '',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_cloud_accounts_tenant" ON "cloud_accounts" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_cloud_accounts_provider" ON "cloud_accounts" ("provider");
CREATE INDEX IF NOT EXISTS "idx_cloud_accounts_status" ON "cloud_accounts" ("status");

CREATE TABLE IF NOT EXISTS "cloud_resources" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "cloud_account_id" varchar(64) NOT NULL,
  "provider" varchar(32) NOT NULL,
  "region" varchar(64) NOT NULL DEFAULT '',
  "resource_type" varchar(64) NOT NULL,
  "resource_id" varchar(256) NOT NULL,
  "resource_name" varchar(256) NOT NULL DEFAULT '',
  "status" varchar(32) NOT NULL DEFAULT 'unknown',
  "tags" text NOT NULL,
  "private_ip" varchar(64) NOT NULL DEFAULT '',
  "public_ip" varchar(64) NOT NULL DEFAULT '',
  "created_at" timestamp NOT NULL DEFAULT now(),
  "updated_at" timestamp NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "uk_cloud_resources_account_res" UNIQUE ("cloud_account_id", "resource_type", "resource_id")
);
CREATE INDEX IF NOT EXISTS "idx_cloud_resources_tenant" ON "cloud_resources" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_cloud_resources_account" ON "cloud_resources" ("cloud_account_id");
CREATE INDEX IF NOT EXISTS "idx_cloud_resources_type" ON "cloud_resources" ("resource_type");

CREATE TABLE IF NOT EXISTS "compliance_reports" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "device_id" varchar(64),
  "results" text,
  "score" int NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_compliance_tenant" ON "compliance_reports" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_compliance_device" ON "compliance_reports" ("tenant_id", "device_id");
CREATE INDEX IF NOT EXISTS "idx_compliance_created" ON "compliance_reports" ("tenant_id", "created_at");

CREATE TABLE IF NOT EXISTS "config_history" (
  "tenant_id" varchar(64) NOT NULL,
  "key_name" varchar(255) NOT NULL,
  "version" int NOT NULL,
  "value" text,
  "format" varchar(16),
  "description" text,
  "updated_by" varchar(64),
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("tenant_id", "key_name", "version")
);
CREATE INDEX IF NOT EXISTS "idx_config_history_tenant" ON "config_history" ("tenant_id");

CREATE TABLE IF NOT EXISTS "configs" (
  "tenant_id" varchar(64) NOT NULL,
  "key_name" varchar(255) NOT NULL,
  "value" text,
  "format" varchar(16) NOT NULL DEFAULT 'text',
  "version" int NOT NULL DEFAULT 1,
  "description" text,
  "updated_by" varchar(64),
  "updated_at" timestamp NOT NULL,
  "published_at" timestamp,
  PRIMARY KEY ("tenant_id", "key_name")
);
CREATE INDEX IF NOT EXISTS "idx_configs_tenant" ON "configs" ("tenant_id");

CREATE TABLE IF NOT EXISTS "devices" (
  "device_id" varchar(64) NOT NULL,
  "segment" varchar(64),
  "tenant_id" varchar(64),
  "ip" varchar(64),
  "agent_id" varchar(64),
  "state" varchar(16),
  "task_state" varchar(16),
  "managed" smallint DEFAULT 0,
  "last_result" varchar(16),
  "last_result_at" timestamp,
  "retired" smallint DEFAULT 0,
  "hostname" varchar(255),
  "os" varchar(64),
  "arch" varchar(32),
  PRIMARY KEY ("device_id")
);

CREATE TABLE IF NOT EXISTS "gateway_routes" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL DEFAULT '',
  "path_prefix" varchar(512) NOT NULL DEFAULT '',
  "target_backend" varchar(512) NOT NULL DEFAULT '',
  "methods" json,
  "rate_limit_per_sec" int NOT NULL DEFAULT 0,
  "timeout_ms" int NOT NULL DEFAULT 30000,
  "enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamp(3) NOT NULL DEFAULT now(),
  "updated_at" timestamp(3) NOT NULL DEFAULT now(),
  PRIMARY KEY ("tenant_id", "id")
);
CREATE INDEX IF NOT EXISTS "idx_gateway_routes_tenant" ON "gateway_routes" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_gateway_routes_target" ON "gateway_routes" ("target_backend");

CREATE TABLE IF NOT EXISTS "install_tokens" (
  "token" varchar(512) NOT NULL,
  "device_id" varchar(64),
  "tenant_id" varchar(64),
  "expires_at" timestamp,
  "consumed" smallint DEFAULT 0,
  PRIMARY KEY ("token")
);

CREATE TABLE IF NOT EXISTS "invoices" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "subscription_id" varchar(64) NOT NULL,
  "amount" int NOT NULL DEFAULT 0,
  "period_start" timestamp NOT NULL,
  "period_end" timestamp NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'pending',
  "items" text,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_invoices_tenant" ON "invoices" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_invoices_subscription" ON "invoices" ("tenant_id", "subscription_id");
CREATE INDEX IF NOT EXISTS "idx_invoices_status" ON "invoices" ("tenant_id", "status");
CREATE INDEX IF NOT EXISTS "idx_invoices_created" ON "invoices" ("tenant_id", "created_at");

CREATE TABLE IF NOT EXISTS "k8s_clusters" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64),
  "name" varchar(255) NOT NULL,
  "server" varchar(255),
  "kubeconfig" text,
  "status" varchar(16) DEFAULT 'unknown',
  "created_at" timestamp,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "leader_lease" (
  "id" int NOT NULL DEFAULT 1,
  "holder" varchar(128),
  "expires_at" timestamp,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "lifecycle_jobs" (
  "id" varchar(64) NOT NULL,
  "cluster_id" varchar(64) NOT NULL,
  "kind" varchar(32) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "phase" varchar(32) NOT NULL,
  "progress" int NOT NULL DEFAULT 0,
  "current_step" varchar(128) NOT NULL DEFAULT '',
  "spec_json" json,
  "result_json" json,
  "error" varchar(1024) NOT NULL DEFAULT '',
  "lock_owner" varchar(128) NOT NULL DEFAULT '',
  "version" int NOT NULL DEFAULT 0,
  "created_at" timestamp(3) NOT NULL DEFAULT now(),
  "updated_at" timestamp(3) NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_lifecycle_jobs_cluster_kind_created" ON "lifecycle_jobs" ("cluster_id", "kind", "created_at");

CREATE TABLE IF NOT EXISTS "middleware_templates" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64),
  "name" varchar(255) NOT NULL,
  "type" varchar(64),
  "version" varchar(64),
  "config" text,
  "created_at" timestamp,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "network_devices" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "type" varchar(32),
  "vendor" varchar(128),
  "model" varchar(128),
  "ip" varchar(64),
  "mask" varchar(32),
  "mac" varchar(64),
  "location" varchar(255),
  "snmp_community" varchar(255),
  "status" varchar(32) NOT NULL DEFAULT 'unknown',
  "config" text,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_netdev_tenant" ON "network_devices" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_netdev_ip" ON "network_devices" ("tenant_id", "ip");
CREATE INDEX IF NOT EXISTS "idx_netdev_status" ON "network_devices" ("tenant_id", "status");

CREATE TABLE IF NOT EXISTS "network_metrics" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "device_id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "timestamp" timestamp NOT NULL,
  "cpu_usage" double precision NOT NULL DEFAULT 0,
  "memory_usage" double precision NOT NULL DEFAULT 0,
  "temperature" double precision NOT NULL DEFAULT 0,
  "uptime" bigint NOT NULL DEFAULT 0,
