);
CREATE INDEX IF NOT EXISTS "idx_netmetrics_device" ON "network_metrics" ("device_id", "timestamp");

CREATE TABLE IF NOT EXISTS "notify_channels" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL,
  "name" varchar(255) NOT NULL,
  "type" varchar(32) NOT NULL,
  "config" json,
  "enabled" smallint DEFAULT 1,
  "created_at" timestamp,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_notify_channels_tenant" ON "notify_channels" ("tenant_id");

CREATE TABLE IF NOT EXISTS "notify_templates" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL,
  "name" varchar(255) NOT NULL,
  "type" varchar(32) NOT NULL,
  "title" text,
  "body" text,
  "format" varchar(16),
  "created_at" timestamp,
  "updated_at" timestamp,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_notify_templates_tenant" ON "notify_templates" ("tenant_id");

