CREATE TABLE IF NOT EXISTS "plugins" (
  "id" varchar(64) NOT NULL,
  "name" varchar(255) NOT NULL,
  "version" varchar(64),
  "description" text,
  "author" varchar(255),
  "type" varchar(32) NOT NULL DEFAULT 'agent',
  "download_url" text,
  "checksum" varchar(128),
  "installed" smallint NOT NULL DEFAULT 0,
  "enabled" smallint NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_plugins_type" ON "plugins" ("type");
CREATE INDEX IF NOT EXISTS "idx_plugins_name" ON "plugins" ("name");

CREATE TABLE IF NOT EXISTS "quota_configs" (
  "tenant_id" varchar(64) NOT NULL,
  "max_devices" int NOT NULL DEFAULT 0,
  "max_tasks" int NOT NULL DEFAULT 0,
  "max_alerts" int NOT NULL DEFAULT 0,
  "updated_at" timestamp,
  PRIMARY KEY ("tenant_id")
);

CREATE TABLE IF NOT EXISTS "refresh_tokens" (
  "token_hash" varchar(64) NOT NULL,
  "user_id" varchar(64),
  "tenant_id" varchar(64),
  "device_fp" varchar(255),
  "expires_at" timestamp,
  "created_at" timestamp,
  PRIMARY KEY ("token_hash")
);
CREATE INDEX IF NOT EXISTS "idx_refresh_tokens_user" ON "refresh_tokens" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_refresh_tokens_expires" ON "refresh_tokens" ("expires_at");

CREATE TABLE IF NOT EXISTS "roles" (
  "id" varchar(64) NOT NULL,
  "name" varchar(64) NOT NULL,
  "description" varchar(255),
  "permissions" json,
  "created_at" timestamp,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_roles_name" UNIQUE ("name")
);

CREATE TABLE IF NOT EXISTS "script_executions" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "script_id" varchar(64) NOT NULL,
  "device_id" varchar(64),
  "status" varchar(32) NOT NULL DEFAULT 'pending',
  "stdout" text,
  "stderr" text,
  "started_at" timestamp NOT NULL,
  "finished_at" timestamp,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_script_exec_tenant" ON "script_executions" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_script_exec_script" ON "script_executions" ("tenant_id", "script_id");
CREATE INDEX IF NOT EXISTS "idx_script_exec_started" ON "script_executions" ("tenant_id", "started_at");

CREATE TABLE IF NOT EXISTS "scripts" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "language" varchar(32) NOT NULL DEFAULT 'shell',
  "content" text,
  "params" text,
  "timeout_sec" int NOT NULL DEFAULT 0,
  "enabled" smallint NOT NULL DEFAULT 1,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_scripts_tenant" ON "scripts" ("tenant_id");

CREATE TABLE IF NOT EXISTS "secret_access_logs" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "key_name" varchar(256) NOT NULL,
  "accessed_by" varchar(128) NOT NULL DEFAULT '',
  "action" varchar(32) NOT NULL DEFAULT 'get',
  "accessed_at" timestamp NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_secret_access_logs_tenant" ON "secret_access_logs" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_secret_access_logs_key" ON "secret_access_logs" ("key_name");
CREATE INDEX IF NOT EXISTS "idx_secret_access_logs_time" ON "secret_access_logs" ("accessed_at");

CREATE TABLE IF NOT EXISTS "secrets" (
  "tenant_id" varchar(64) NOT NULL,
  "key_name" varchar(255) NOT NULL,
  "version" int NOT NULL,
  "value" text,
  "key_type" varchar(32) NOT NULL DEFAULT 'passphrase',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("tenant_id", "key_name", "version")
);
CREATE INDEX IF NOT EXISTS "idx_secrets_tenant" ON "secrets" ("tenant_id");

CREATE TABLE IF NOT EXISTS "services" (
  "service_id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL,
  "service_name" varchar(255) NOT NULL,
  "address" varchar(255),
  "port" int,
  "metadata" text,
  "status" varchar(16) NOT NULL DEFAULT 'healthy',
  "last_heartbeat" timestamp NOT NULL,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("service_id")
);
CREATE INDEX IF NOT EXISTS "idx_services_tenant" ON "services" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_services_name" ON "services" ("tenant_id", "service_name");

CREATE TABLE IF NOT EXISTS "slos" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "description" text,
  "service_name" varchar(255),
  "target" double precision NOT NULL DEFAULT 0,
  "window_spec" varchar(32),
  "slis" text,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_slos_tenant" ON "slos" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_slos_service" ON "slos" ("tenant_id", "service_name");

CREATE TABLE IF NOT EXISTS "subscriptions" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "plan_id" varchar(64) NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'active',
  "started_at" timestamp NOT NULL,
  "expires_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_subscriptions_tenant" ON "subscriptions" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_subscriptions_plan" ON "subscriptions" ("tenant_id", "plan_id");
CREATE INDEX IF NOT EXISTS "idx_subscriptions_status" ON "subscriptions" ("tenant_id", "status");

CREATE TABLE IF NOT EXISTS "task_records" (
  "kind" varchar(16) NOT NULL,
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "created_at" timestamp(3) NOT NULL DEFAULT now(),
  "payload" json NOT NULL,
  PRIMARY KEY ("tenant_id", "kind", "id")
);
CREATE INDEX IF NOT EXISTS "idx_task_records_kind_created" ON "task_records" ("kind", "created_at");

CREATE TABLE IF NOT EXISTS "task_results" (
  "task_id" varchar(64) NOT NULL,
  "agent_id" varchar(64),
  "exit_code" int,
  "stdout" text,
  "stderr" text,
  "finished_at" timestamp,
  PRIMARY KEY ("task_id")
);

CREATE TABLE IF NOT EXISTS "tasks" (
  "task_id" varchar(64) NOT NULL,
  "agent_id" varchar(64),
  "tenant_id" varchar(64),
  "type" varchar(32),
  "command" text,
  "content" text,
  "path" varchar(512),
  "status" varchar(16),
  "claimed_by" varchar(64),
  "claimed_at" timestamp,
  "created_at" timestamp,
  "retry_count" int DEFAULT 0,
  "max_retries" int DEFAULT 0,
  "dead_letter" smallint DEFAULT 0,
  "schedule" varchar(64),
  "parent_id" varchar(64),
  "last_fired_at" timestamp,
  "depends_on" text,
  "timeout" int DEFAULT 0,
  "retry_delay" int DEFAULT 0,
  "claim_epoch" bigint NOT NULL DEFAULT 0,
  "priority" int DEFAULT 0,
  "idempotency_key" varchar(128),
  "approval_required" smallint NOT NULL DEFAULT 0,
  "script_body" text,
  "approved_by" varchar(64),
  "approved_at" timestamp,
  PRIMARY KEY ("task_id")
);
CREATE INDEX IF NOT EXISTS "idx_tasks_tenant_created" ON "tasks" ("tenant_id", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "idx_tasks_agent" ON "tasks" ("agent_id", "status");

CREATE TABLE IF NOT EXISTS "tenants" (
  "id" varchar(64) NOT NULL,
  "name" varchar(128) NOT NULL,
  "display_name" varchar(255),
  "status" varchar(32) NOT NULL DEFAULT 'active',
  "quota" text,
  "usage_data" text,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_tenants_name" UNIQUE ("name")
);
CREATE INDEX IF NOT EXISTS "idx_tenants_status" ON "tenants" ("status");

CREATE TABLE IF NOT EXISTS "tickets" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "title" varchar(255) NOT NULL,
  "description" text,
  "status" varchar(32) NOT NULL DEFAULT 'open',
  "priority" varchar(32) NOT NULL DEFAULT 'medium',
  "category" varchar(32) NOT NULL DEFAULT 'incident',
  "assignee_id" varchar(64),
  "creator_id" varchar(64),
  "related_device" varchar(64),
  "related_task" varchar(64),
  "tags" text,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "resolved_at" timestamp,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_tickets_tenant" ON "tickets" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_tickets_status" ON "tickets" ("tenant_id", "status");
CREATE INDEX IF NOT EXISTS "idx_tickets_priority" ON "tickets" ("tenant_id", "priority");
CREATE INDEX IF NOT EXISTS "idx_tickets_assignee" ON "tickets" ("tenant_id", "assignee_id");
CREATE INDEX IF NOT EXISTS "idx_tickets_created" ON "tickets" ("tenant_id", "created_at");

CREATE TABLE IF NOT EXISTS "traffic_policies" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "service_name" varchar(255),
  "type" varchar(32) NOT NULL,
  "canary_weights" text,
  "mirror_percent" int NOT NULL DEFAULT 0,
  "timeout" varchar(32),
  "retries" int NOT NULL DEFAULT 0,
  "retry_timeout" varchar(32),
  "max_conns" int NOT NULL DEFAULT 0,
  "max_requests" int NOT NULL DEFAULT 0,
  "status" varchar(32) NOT NULL DEFAULT 'inactive',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_traffic_tenant" ON "traffic_policies" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_traffic_service" ON "traffic_policies" ("tenant_id", "service_name");
CREATE INDEX IF NOT EXISTS "idx_traffic_status" ON "traffic_policies" ("tenant_id", "status");

CREATE TABLE IF NOT EXISTS "users" (
  "id" varchar(64) NOT NULL,
  "username" varchar(64) NOT NULL,
  "email" varchar(255),
  "password_hash" varchar(255),
  "status" varchar(16) DEFAULT 'active',
  "role_ids" json,
  "created_at" timestamp,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "must_change_password" boolean DEFAULT false,
  PRIMARY KEY ("id"),
  CONSTRAINT "username" UNIQUE ("username")
);

CREATE TABLE IF NOT EXISTS "webhook_deliveries" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "webhook_id" varchar(64) NOT NULL,
  "event" varchar(255),
  "payload" text,
  "status_code" int NOT NULL DEFAULT 0,
  "response" text,
  "error" text,
  "delivered_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_webhook_deliv_tenant" ON "webhook_deliveries" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_webhook_deliv_webhook" ON "webhook_deliveries" ("tenant_id", "webhook_id");
CREATE INDEX IF NOT EXISTS "idx_webhook_deliv_delivered" ON "webhook_deliveries" ("tenant_id", "delivered_at");

CREATE TABLE IF NOT EXISTS "webhooks" (
  "id" varchar(64) NOT NULL,
  "tenant_id" varchar(64) NOT NULL DEFAULT 'default',
  "name" varchar(255) NOT NULL,
  "url" text,
  "events" text,
  "headers" text,
  "body_template" text,
  "enabled" smallint NOT NULL DEFAULT 1,
  "retry_count" int NOT NULL DEFAULT 0,
  "retry_interval_sec" int NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_webhooks_tenant" ON "webhooks" ("tenant_id");
CREATE INDEX IF NOT EXISTS "idx_webhooks_enabled" ON "webhooks" ("tenant_id", "enabled");

-- 列/表注释（与 MySQL 侧 COMMENT 逐字对齐）
COMMENT ON COLUMN "gateway_routes"."id" IS '规则 ID（gw- 前缀随机串）';
COMMENT ON COLUMN "gateway_routes"."tenant_id" IS '归属租户（隔离键）';
COMMENT ON COLUMN "gateway_routes"."name" IS '规则名（展示用）';
COMMENT ON COLUMN "gateway_routes"."path_prefix" IS '匹配的路径前缀（已含 /gw 剥前缀）';
COMMENT ON COLUMN "gateway_routes"."target_backend" IS '后端地址 scheme://host:port（http|https）';
COMMENT ON COLUMN "gateway_routes"."methods" IS '允许的 HTTP 方法列表；NULL=全部方法';
COMMENT ON COLUMN "gateway_routes"."rate_limit_per_sec" IS '路由级令牌桶速率；0=不限流';
COMMENT ON COLUMN "gateway_routes"."timeout_ms" IS '单路由转发超时（TD-66 P4）';
COMMENT ON COLUMN "gateway_routes"."enabled" IS '是否启用（禁用则不参与匹配）';
COMMENT ON COLUMN "gateway_routes"."created_at" IS '创建时间';
COMMENT ON COLUMN "gateway_routes"."updated_at" IS '更新时间';
COMMENT ON TABLE "gateway_routes" IS 'API 网关路由规则（TD-66 P1 持久化）';

COMMENT ON COLUMN "lifecycle_jobs"."id" IS '作业 ID';
COMMENT ON COLUMN "lifecycle_jobs"."cluster_id" IS '目标集群';
COMMENT ON COLUMN "lifecycle_jobs"."kind" IS '作业类型：upgrade | rollback | cert-rotate';
COMMENT ON COLUMN "lifecycle_jobs"."tenant_id" IS '归属租户（隔离键）';
COMMENT ON COLUMN "lifecycle_jobs"."phase" IS 'pending/precheck/running/.../completed/failed/cancelled';
COMMENT ON COLUMN "lifecycle_jobs"."progress" IS '进度百分比';
COMMENT ON COLUMN "lifecycle_jobs"."current_step" IS '当前步骤';
COMMENT ON COLUMN "lifecycle_jobs"."spec_json" IS '作业规格（创建时快照）';
COMMENT ON COLUMN "lifecycle_jobs"."result_json" IS '执行结果（终态时写入）';
COMMENT ON COLUMN "lifecycle_jobs"."error" IS '失败原因（读侧 Scan 进 string，须非 NULL）';
COMMENT ON COLUMN "lifecycle_jobs"."lock_owner" IS '乐观锁持有者（读侧 Scan 进 string，须非 NULL）';
COMMENT ON COLUMN "lifecycle_jobs"."version" IS '乐观锁版本号（UPDATE 时 +1）';
COMMENT ON COLUMN "lifecycle_jobs"."created_at" IS '创建时间';
COMMENT ON COLUMN "lifecycle_jobs"."updated_at" IS '更新时间';
COMMENT ON TABLE "lifecycle_jobs" IS 'K8s 生命周期作业（升级/回滚/证书轮换）';

COMMENT ON COLUMN "task_records"."kind" IS '记录类型：batch | canary';
COMMENT ON COLUMN "task_records"."id" IS '记录 ID（batch- / canary- 前缀）';
COMMENT ON COLUMN "task_records"."tenant_id" IS '归属租户（隔离键）';
COMMENT ON COLUMN "task_records"."payload" IS '记录内容（控制面内部结构序列化；非对外契约）';
COMMENT ON TABLE "task_records" IS '批量/灰度记录（TD-60 task 域 R6 持久化）';

COMMENT ON TABLE "cloud_accounts" IS '云账号（Wave 2-B 多云基础设施）';
COMMENT ON TABLE "cloud_resources" IS '云资源（Wave 2-B 多云基础设施）';
